package run.ikaros.password; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import run.ikaros.common.NotFoundException; import reactor.core.publisher.Mono; @Service public class PasswordFavoriteService{private final PasswordVaultRepository vaults;private final PasswordVaultItemRepository items;public PasswordFavoriteService(PasswordVaultRepository v,PasswordVaultItemRepository i){vaults=v;items=i;}public Flux<PasswordVaultItemView> list(UUID a,UUID vaultId){return vaults.findById(vaultId).filter(v->v.ownerId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("Password Vault 不存在或无权访问"))).flatMapMany(v->items.findAllByVaultIdAndOwnerIdAndFavoriteTrueAndTombstoneFalseOrderByUpdatedAtDesc(vaultId,a).map(i->new PasswordVaultItemView(i.id(),i.vaultId(),i.itemType(),i.encryptedName(),i.encryptedPayload(),i.encryptedCustomFields(),i.favorite(),i.revision(),i.tombstone(),i.createdAt(),i.updatedAt())));}}
